const plans = $('BL Plan').all().map(i => i.json).filter(p => !p.nothing_to_do);
const merged = $('Link Merge').all().map(i => i.json).filter(m => !m.skip && !(plans.find(p => p.site_id === m.site_id) || {}).free_only);   // free_only: Common Crawl ranks only
