      links: chunk.map((x, k) => (k + 1) + '. ' + x.v.ref_domain + ' — "' + String(x.v.title || '').slice(0, 110) + '" | ' + (x.v.placement || 'body') + (x.v.rel && x.v.rel !== 'follow' ? ' | ' + x.v.rel : '') + ' | anchor: "' + String(x.v.anchor || '').slice(0, 80) + '" | text: ' + String(x.v.context || '').slice(0, 300)).join('\n') } });
